INSERT INTO words (english, translation, example, meaning) VALUES ('Be', 'быть, являться', 'I want to be a doctor.', 'Be — быть; формы: am, is, are (настоящее), was, were (прошедшее).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Am', 'я есть (форма be)', 'I am ready.', 'Am — форма глагола be только для I.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Is', 'он/она/оно есть', 'She is happy.', 'Is — форма be для he, she, it.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Are', 'мы/ты/они есть', 'We are friends.', 'Are — форма be для we, you, they.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Was', 'был, была, было', 'It was cold yesterday.', 'Was — прошедшая форма be для I, he, she, it.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Were', 'были', 'We were at home.', 'Were — прошедшая форма be для we, you, they.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Been', 'был (причастие be)', 'I have been to Paris.', 'Been — причастие be; have been to — побывать где-то.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Do', 'делать; вспомогательный глагол', 'Do you like tea?', 'Do — делать; образует вопросы и отрицания в Present Simple.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Does', 'делает (3 лицо)', 'She does her homework.', 'Does — форма do для he, she, it.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Did', 'делал (прошедшее)', 'Did you sleep well?', 'Did — прошедшая форма do; вспомогательный глагол в Past Simple.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Done', 'сделанный', 'Well done!', 'Done — причастие от do; well done — молодец!') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Make', 'делать, создавать', 'Make a cup of tea.', 'Make — делать, создавать что-то новое; Do — выполнять действие.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Made', 'сделал', 'She made a cake.', 'Made — прошедшая форма и причастие от make.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Has', 'имеет (3 лицо)', 'He has a car.', 'Has — форма have для he, she, it.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Had', 'имел', 'I had a dog when I was little.', 'Had — прошедшая форма have.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Can', 'мочь, уметь', 'I can swim.', 'Can — уметь, мочь; Can I...? — вежливая просьба.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Could', 'мог бы', 'Could you help me, please?', 'Could — прошедшая форма can; вежливая просьба.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Will', 'буду (будущее время)', 'I will call you tomorrow.', 'Will — вспомогательный глагол будущего времени.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Would', 'бы', 'I would like a coffee.', 'Would — бы; would like — вежливое «хочу».') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Should', 'следует, нужно', 'You should rest.', 'Should — совет: тебе следует.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Must', 'должен', 'You must stop at the red light.', 'Must — должен (строгая обязанность).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('May', 'можно, возможно', 'May I come in?', 'May — можно (разрешение); возможно.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Might', 'возможно, может быть', 'It might rain later.', 'Might — может быть (неуверенность).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Shall', '(вежливое предложение)', 'Shall we dance?', 'Shall — вежливое предложение: shall we...?') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Let', 'позволять', 'Let me help you.', 'Let — позволять; let me — позволь мне.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('I', 'я', 'I am a student.', 'I — я; всегда пишется с большой буквы.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('You', 'ты, вы', 'You are my friend.', 'You — ты и вы (одно слово для одного и многих).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('He', 'он', 'He is my brother.', 'He — он (о мужчине или мальчике).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('She', 'она', 'She likes music.', 'She — она (о женщине или девочке).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('It', 'оно, это', 'It is raining.', 'It — оно, это (о предметах, животных, явлениях).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('We', 'мы', 'We go to school.', 'We — мы.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('They', 'они', 'They live in Moscow.', 'They — они (о людях, животных, предметах).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Me', 'меня, мне', 'Call me, please.', 'Me — меня, мне (после глагола или предлога).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Him', 'его, ему', 'I know him.', 'Him — его, ему.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Us', 'нас, нам', 'Help us!', 'Us — нас, нам.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Them', 'их, им', 'I see them.', 'Them — их, им.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('My', 'мой, моя, моё', 'This is my house.', 'My — мой, моя, моё, мои.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Your', 'твой, ваш', 'Is this your bag?', 'Your — твой, ваш.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('His', 'его (принадлежность)', 'His car is new.', 'His — его (принадлежит ему).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Our', 'наш', 'Our family is big.', 'Our — наш.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Their', 'их (принадлежность)', 'Their dog is small.', 'Their — их (принадлежит им).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Its', 'его, её (о предмете)', 'The cat licked its paw.', 'Its — его, её о предмете или животном; без апострофа.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Mine', 'мой (без существительного)', 'This book is mine.', 'Mine — мой, без существительного после себя.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Yours', 'твой, ваш (без существительного)', 'Is this pen yours?', 'Yours — твой, ваш, без существительного.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Hers', 'её (без существительного)', 'This coat is hers.', 'Hers — её, без существительного.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Ours', 'наш (без существительного)', 'The house is ours.', 'Ours — наш, без существительного.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Theirs', 'их (без существительного)', 'The toys are theirs.', 'Theirs — их, без существительного.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('This', 'этот, эта, это', 'This is my friend.', 'This — этот (рядом); мн. ч. these.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('That', 'тот, та, то; что', 'That car is fast.', 'That — тот (далеко); союз «что»: I know that he is busy.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('These', 'эти', 'These shoes are new.', 'These — эти (мн. ч. от this).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Those', 'те', 'Those people are tourists.', 'Those — те (мн. ч. от that).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Who', 'кто', 'Who are you?', 'Who — кто; о людях.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('What', 'что, какой', 'What is your name?', 'What — что, какой; what time? — во сколько?') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Where', 'где, куда', 'Where do you live?', 'Where — где, куда.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('When', 'когда', 'When is your birthday?', 'When — когда.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Why', 'почему', 'Why are you late?', 'Why — почему; в ответе — because.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('How', 'как', 'How are you?', 'How — как; how much? — сколько?') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Which', 'который, какой', 'Which book is yours?', 'Which — который, какой (выбор из нескольких).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Because', 'потому что', 'I am late because of traffic.', 'Because — потому что; because of — из-за.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('So', 'поэтому, так, такой', 'I was tired, so I went to bed.', 'So — поэтому; так; такой; so do I — я тоже.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('But', 'но', 'I like tea, but I do not like coffee.', 'But — но, однако.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('And', 'и', 'Bread and butter.', 'And — и; соединяет слова и части предложения.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Or', 'или', 'Tea or coffee?', 'Or — или.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('If', 'если', 'If it rains, we stay home.', 'If — если; if I were you — на твоём месте.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Than', 'чем', 'She is taller than me.', 'Than — чем (при сравнении).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Also', 'также, тоже', 'I also like music.', 'Also — также, тоже; стоит перед смысловым глаголом.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Too', 'тоже; слишком', 'Nice to meet you too.', 'Too — тоже (в конце); слишком: too hot.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Only', 'только', 'There are only two tickets.', 'Only — только, лишь.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Just', 'только что; просто', 'I have just finished.', 'Just — только что; просто: it is just a joke.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Very', 'очень', 'The film was very good.', 'Very — очень; усиливает прилагательное или наречие.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Really', 'действительно, очень', 'It is really cold.', 'Really — действительно, очень; also «правда?».') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Quite', 'довольно, вполне', 'The task is quite easy.', 'Quite — довольно, вполне; quite good — неплохо.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Not', 'не', 'I am not tired.', 'Not — не; отрицательная частица.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('No', 'нет; никакой', 'No, thank you.', 'No — нет; никакой: no money.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Yes', 'да', 'Yes, I understand.', 'Yes — да.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Maybe', 'может быть', 'Maybe tomorrow.', 'Maybe — может быть, возможно (неуверенность).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Perhaps', 'возможно, пожалуй', 'Perhaps we should leave.', 'Perhaps — возможно, пожалуй (формальнее, чем maybe).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('With', 'с, вместе с', 'I live with my parents.', 'With — с, вместе с.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Without', 'без', 'I cannot live without coffee.', 'Without — без.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('About', 'о, об; около', 'The book is about animals.', 'About — о, об; примерно: about ten people.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('For', 'для, за, в течение', 'This present is for you.', 'For — для; за; в течение: for two hours.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('From', 'из, от', 'I am from Russia.', 'From — из, от (исходная точка).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('To', 'к, в (направление)', 'I go to school.', 'To — к, в (направление); частица перед глаголом: to read.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Into', 'в, внутрь', 'The cat jumped into the box.', 'Into — в, внутрь (движение).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('On', 'на; в (дни недели)', 'The book is on the table.', 'On — на (поверхность); on Monday — в понедельник.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('In', 'в, внутри', 'She is in the kitchen.', 'In — в, внутри; in summer — летом.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('At', 'у, в, на (точка)', 'Meet me at the station.', 'At — у, в, на (конкретная точка): at school, at five.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('By', 'у, около; к (сроку)', 'The book is by a famous writer.', 'By — авторство; к сроку: by Monday; by bus — на автобусе.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Under', 'под', 'The cat is under the chair.', 'Under — под.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Over', 'над; через; закончено', 'The game is over.', 'Over — над; через; закончено: the game is over.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Above', 'над, выше', 'The plane flies above the clouds.', 'Above — над, выше (без контакта).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Below', 'ниже, под (уровень)', 'The temperature is below zero.', 'Below — ниже, под (об уровне).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Between', 'между (двумя)', 'The shop is between the bank and the hotel.', 'Between — между двумя; among — среди многих.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Behind', 'за, позади', 'The garden is behind the house.', 'Behind — за, позади.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Near', 'рядом, близко', 'There is a shop near my house.', 'Near — рядом, близко; next to — вплотную.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Across', 'через (поверхность)', 'There is a bridge across the river.', 'Across — через (поверхность): across the road.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Around', 'вокруг; около', 'We walked around the park.', 'Around — вокруг; примерно: around five o''clock.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Through', 'сквозь, через', 'We drove through the tunnel.', 'Through — сквозь, через (насквозь).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('After', 'после; за', 'We play football after school.', 'After — после; за (следовать).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Before', 'до, перед', 'Wash your hands before dinner.', 'Before — до, перед; раньше.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('During', 'во время', 'Please be quiet during the film.', 'During — во время, в течение.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Until', 'до (о времени)', 'I work until five.', 'Until — до (о времени): until Monday.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Since', 'с (о времени)', 'I have lived here since 2020.', 'Since — с (момент); с тех пор как.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Ago', 'назад (о времени)', 'We met two years ago.', 'Ago — назад: two days ago — два дня назад.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Again', 'снова, опять', 'Could you say that again, please?', 'Again — снова, опять.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Here', 'здесь, сюда', 'Come here!', 'Here — здесь, сюда.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('There', 'там, туда; есть', 'Put the box there.', 'There — там, туда; there is/are — есть, имеется.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Away', 'прочь, далеко', 'Go away!', 'Away — прочь, далеко; go away — уходить.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Back', 'назад; спина', 'Come back!', 'Back — назад; спина; come back — вернуться.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Up', 'вверх', 'Look up!', 'Up — вверх; get up — вставать.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Down', 'вниз', 'Sit down, please.', 'Down — вниз; sit down — садиться.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Out', 'наружу, из', 'Take the cake out of the box.', 'Out — наружу; go out — выходить.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Off', 'с (поверхности); выключено', 'Take your shoes off.', 'Off — с (поверхности); выключено: turn off.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Then', 'тогда, потом', 'We had dinner, then we watched a film.', 'Then — тогда, потом, затем.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Still', 'всё ещё', 'Are you still at work?', 'Still — всё ещё, по-прежнему.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Yet', 'ещё (в отрицаниях), уже (в вопросах)', 'I have not finished yet.', 'Yet — ещё не (в отрицаниях); уже (в вопросах).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Already', 'уже', 'I have already eaten.', 'Already — уже (раньше, чем ожидалось).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Ever', 'когда-либо', 'Have you ever been to London?', 'Ever — когда-либо; в вопросах и отрицаниях.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Once', 'однажды; один раз', 'Once there lived a king.', 'Once — однажды; один раз.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Twice', 'дважды', 'Brush your teeth twice a day.', 'Twice — дважды, два раза.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Some', 'немного, несколько', 'Would you like some tea?', 'Some — немного, несколько (в утверждениях и вежливых просьбах).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Any', 'сколько-нибудь, нисколько', 'Do you have any questions?', 'Any — сколько-нибудь (в вопросах), нисколько (в отрицаниях).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Much', 'много (неисчисляемое)', 'How much money do you have?', 'Much — много (с неисчисляемыми); how much? — сколько?') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Many', 'много (исчисляемое)', 'Many people live in the city.', 'Many — много (с исчисляемыми); how many? — сколько?') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Few', 'мало; несколько', 'A few friends came to the party.', 'Few — мало; a few — несколько (с исчисляемыми).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('All', 'все, всё', 'All the children are at school.', 'All — все, всё, весь.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Both', 'оба', 'Both answers are correct.', 'Both — оба; both... and... — и... и...') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Each', 'каждый', 'Each student has a book.', 'Each — каждый (по отдельности).') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Every', 'каждый', 'I swim every day.', 'Every — каждый; every day — каждый день.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Other', 'другой, другие', 'Do you have other questions?', 'Other — другой, другие.') ON CONFLICT DO NOTHING;
INSERT INTO words (english, translation, example, meaning) VALUES ('Another', 'ещё один, другой', 'Would you like another cup of tea?', 'Another — ещё один, другой.') ON CONFLICT DO NOTHING;
